node <<'NODE'
'use strict';
const assert = require('assert');
const EventEmitter = require('./');

const emitter = new EventEmitter();
const context = {};
const calls = [];
function listener() { calls.push(this); }
emitter.on('event', listener, context);
emitter.once('event', listener, context);
const unsubscribe = emitter.subscribe('event', listener, context);
assert.deepStrictEqual(emitter.listeners('event'), [listener, listener, listener]);
unsubscribe();
unsubscribe();
assert.strictEqual(emitter.listenerCount('event'), 2);
emitter.emit('event');
assert.deepStrictEqual(calls, [context, context]);

const stale = new EventEmitter();
function stable() {}
const cancelStale = stale.subscribe('event', stable);
stale.off('event', stable);
stale.on('event', stable);
cancelStale();
assert.deepStrictEqual(stale.listeners('event'), [stable]);
stale.removeAllListeners('event');
const cancelRemoved = stale.subscribe('event', stable);
stale.removeAllListeners('event');
stale.subscribe('event', stable);
cancelRemoved();
assert.deepStrictEqual(stale.listeners('event'), [stable]);

const forwarded = new EventEmitter();
let received;
forwarded.subscribe('event', function () {
  received = [this, Array.from(arguments)];
}, context);
forwarded.emit('event', 0, 1, 2, 3, 4, 5, 6, 7, 8);
assert.deepStrictEqual(received, [context, [0, 1, 2, 3, 4, 5, 6, 7, 8]]);

const symbolEmitter = new EventEmitter();
const symbol = Symbol('event');
const cancelSymbol = symbolEmitter.subscribe(symbol, function () {});
assert.deepStrictEqual(symbolEmitter.eventNames(), [symbol]);
cancelSymbol();
assert.deepStrictEqual(symbolEmitter.eventNames(), []);

const invalid = new EventEmitter();
invalid.on('event', listener);
assert.throws(() => invalid.subscribe('event', null));
assert.deepStrictEqual(invalid.listeners('event'), [listener]);

const dispatch = new EventEmitter();
const dispatchCalls = [];
let cancelSecond;
dispatch.subscribe('event', () => {
  dispatchCalls.push('first');
  cancelSecond();
});
cancelSecond = dispatch.subscribe('event', () => dispatchCalls.push('second'));
dispatch.emit('event');
dispatch.emit('event');
assert.deepStrictEqual(dispatchCalls, ['first', 'second', 'first']);

const recursive = new EventEmitter();
let recursiveCalls = 0;
let cancelRecursive;
cancelRecursive = recursive.subscribe('event', () => {
  recursiveCalls++;
  cancelRecursive();
  recursive.emit('event');
});
recursive.emit('event');
assert.strictEqual(recursiveCalls, 1);
assert.strictEqual(recursive.emit('event'), false);
NODE
